ems', null, null, null, false, null, null, null, '{}'::text[], 'Hutchison 24e, Ch 1, p8 (Box 1.7)', true) on conflict (id) do update set complaint_id=excluded.complaint_id, section=excluded.section, ord=excluded.ord, qtype=excluded.qtype, options=excluded.options, text_en=excluded.text_en, text_hi=excluded.text_hi, text_mr=excluded.text_mr, clinical_term=excluded.clinical_term, dedupe_key=excluded.dedupe_key, show_if=excluded.show_if, applies_to=excluded.applies_to, red_flag=excluded.red_flag, red_flag_note=excluded.red_flag_note, positive_means=excluded.positive_means, negative_means=excluded.negative_means, differentials=excluded.differentials, source=excluded.source, active=excluded.active, reviewed_on=current_date;
