, positive_means=excluded.positive_means, negative_means=excluded.negative_means, differentials=excluded.differentials, source=excluded.source, active=excluded.active, reviewed_on=current_date;
insert into public.hx_questions(id, complaint_id, section, ord, qtype, options, text_en, text_hi, text_mr, clinical_term, dedupe_key, show_if, applies_to, red_flag, red_flag_note, positive_means, negative_means, differentials, source, active) values ('cp_relief', 'chest_pain', 'hopi', 7, 'multi', '[{"v": "rest", "en": "Rest (within minutes)", "hi": "आराम करने से (कुछ मिनट में)", "mr": "विश्रांतीने (काही मिनिटांत)", "ddx": ["Angina / ACS"]}, {"v": "sorbitrate", "en": "Tablet under tongue (Sorbitrate / NTG)", "hi": "जीभ के नीचे की गोली (सॉर्बिट्रेट)", "mr": "जिभेखालची गोळी (सॉर्बिट्रेट)", "ddx": ["Angina / ACS", "Oesophageal spasm"]}, {"v": "antacid", "en": "Antacid / gel / food", "hi": "एंटासिड / जेल / खाना", "mr": "अँटासिड / जेल / अन्न", "ddx": ["Reflux / GORD", "Peptic ulcer / gastritis"]}, {"v": "sit_forward", "en": "Sitting up, leaning forward", "hi": "आगे झुककर बैठना", "mr": "पुढे वाकून बसणे", "ddx": ["Pericarditis"]}, {"v": "nothing", "en": "Nothing helps", "hi": "किसी से आराम नहीं", "mr": "कशानेच आराम नाही", "ddx": ["Angina / ACS", "Aortic dissection"]}]'::jsonb, 'What makes it better?', 'किससे आराम मिलता है?', 'कशाने आराम मिळतो?', 'Relieving factors', null, null, null, false, null, null, null, '{}'::text[], 'Hutchison 24e, Ch 13, p190-191', true) on conflict (id) do update set complaint_id=excluded.complaint_id, section=excluded.section, ord=excluded.ord, qtype=excluded.qtype, options=excluded.options, text_en=excluded.text_en, text_hi=excluded.text_hi, text_mr=excluded.text_mr, clinical_term=excluded.clinical_term, dedupe_key=excluded.dedupe_key, show_if=excluded.show_if, applies_to=excluded.applies_to, red_flag=excluded.red_flag, red_flag_note=excluded.red_flag_note, positive_means=excluded.positive_means, negative_means=excluded.negative_means, differentials=excluded.differentials, source=excluded.source, active=excluded.active, reviewed_on=current_date;
