insert into public.hx_questions(id, complaint_id, section, ord, qtype, options, text_en, text_hi, text_mr, clinical_term, dedupe_key, show_if, applies_to, red_flag, red_flag_note, positive_means, negative_means, differentials, source, active) values ('pa_duration', 'palpitations', 'hopi', 4, 'choice', '[{"v": "seconds", "en": "Seconds", "hi": "कुछ सेकंड", "mr": "काही सेकंद", "ddx": ["Ectopic beats (usually benign)"]}, {"v": "minutes", "en": "Minutes", "hi": "कुछ मिनट", "mr": "काही मिनिटे", "ddx": ["SVT / tachyarrhythmia", "Atrial fibrillation", "Anxiety / panic"]}, {"v": "hours", "en": "Hours or continuous", "hi": "घंटों या लगातार", "mr": "तासन्तास किंवा सतत", "ddx": ["Atrial fibrillation", "Sinus tachycardia", "Thyrotoxicosis"]}]'::jsonb, 'How long does each attack last?', 'हर बार कितनी देर रहती है?', 'प्रत्येक वेळी किती वेळ राहते?', 'Duration of attacks', null, null, null, false, null, null, null, '{}'::text[], 'Hutchison 24e, Ch 13, p194', true) on conflict (id) do update set complaint_id=excluded.complaint_id, section=excluded.section, ord=excluded.ord, qtype=excluded.qtype, options=excluded.options, text_en=excluded.text_en, text_hi=excluded.text_hi, text_mr=excluded.text_mr, clinical_term=excluded.clinical_term, dedupe_key=excluded.dedupe_key, show_if=excluded.show_if, applies_to=excluded.applies_to, red_flag=excluded.red_flag, red_flag_note=excluded.red_flag_note, positive_means=excluded.positive_means, negative_means=excluded.negative_means, differentials=excluded.differentials, source=excluded.source, active=excluded.active, reviewed_on=current_date;
insert into public.hx_questions(id, complaint_id, section, ord, qtype, options, text_en, text_hi, text_mr, clinical_term, dedupe_key, show_if, applies_to, red_flag, red_flag_note, positive_means, negative_means, differentials, source, active) values ('pa_vagal', 'palpitations', 'hopi', 5, 'yesno', null, 'Stops by holding breath and straining, or splashing cold water on face?', 'क्या साँस रोककर ज़ोर लगाने या चेहरे पर ठंडा पानी डालने से रुक जाती है?', 'श्वास रोखून जोर लावल्याने किंवा चेहऱ्यावर थंड पाणी मारल्याने थांबते का?', 'Terminated by vagal manoeuvres', null, '{"q": "pa_onset", "eq": "yes"}'::jsonb, null, false, null, null, null, array['SVT / tachyarrhythmia']::text[], 'General clinical practice', true) on conflict (id) do update set complaint_id=excluded.complaint_id, section=excluded.section, ord=excluded.ord, qtype=excluded.qtype, options=excluded.options, text_en=excluded.text_en, text_hi=excluded.text_hi, text_mr=excluded.text_mr, clinical_term=excluded.clinical_term, dedupe_key=excluded.dedupe_key, show_if=excluded.show_if, applies_to=excluded.applies_to, red_flag=excluded.red_flag, red_flag_note=excluded.red_flag_note, positive_means=excluded.positive_means, negative_means=excluded.negative_means, differentials=excluded.differentials, source=excluded.source, active=excluded.active, reviewed_on=current_date;
insert into public.hx_questions(id, complaint_id, section, ord, qtype, options, text_en, text_hi, text_mr, clinical_term, dedupe_key, show_if, applies_to, red_flag, red_flag_note, positive_means, negative_means, differentials, source, active) values ('pa_triggers', 'palpitations', 'hopi', 6, 'multi', '[{"v": "exercise", "en": "Exercise", "hi": "कसरत / मेहनत", "mr": "व्यायाम / श्रम", "ddx": ["Exercise-induced arrhythmia"]}, {"v": "tea_coffee", "en": "Tea / coffee / energy drinks", "hi": "चाय / कॉफ़ी / एनर्जी ड्रिंक", "mr": "चहा / कॉफी / एनर्जी ड्रिंक", "ddx": ["Ectopic beats (usually benign)", "Sinus tachycardia"]}, {"v": "alcohol", "en": "Alcohol", "hi": "शराब", "mr": "दारू", "ddx": ["Atrial fibrillation"]}, {"v": "stress", "en": "Stress / fear", "hi": "तनाव / डर", "mr": "ताण / भीती", "ddx": ["Anxiety / panic", "Sinus tachycardia"]}, {"v": "lying_left", "en": "Lying down at night", "hi": "रात को लेटने पर", "mr": "रात्री झोपल्यावर", "ddx": ["Ectopic beats (usually benign)"]}, {"v": "none", "en": "No trigger", "hi": "बिना किसी कारण", "mr": "कोणत्याही कारणाशिवाय", "ddx": ["SVT / tachyarrhythmia", "Atrial fibrillation"]}]'::jsonb, 'What brings it on?', 'किस चीज़ से शुरू होती है?', 'कशामुळे सुरू होते?', 'Triggers', null, null, null, false, null, null, null, '{}'::text[], 'Hutchison 24e, Ch 13, p194', true) on conflict (id) do update set complaint_id=excluded.complaint_id, section=excluded.section, ord=excluded.ord, qtype=excluded.qtype, options=excluded.options, text_en=excluded.text_en, text_hi=excluded.text_hi, text_mr=excluded.text_mr, clinical_term=excluded.clinical_term, dedupe_key=excluded.dedupe_key, show_if=excluded.show_if, applies_to=excluded.applies_to, red_flag=excluded.red_flag, red_flag_note=excluded.red_flag_note, positive_means=excluded.positive_means, negative_means=excluded.negative_means, differentials=excluded.differentials, source=excluded.source, active=excluded.active, reviewed_on=current_date;
insert into public.hx_questions(id, complaint_id, section, ord, qtype, options, text_en, text_hi, text_mr, clinical_term, dedupe_key, show_if, applies_to, red_flag, red_flag_note, positive_means, negative_means, differentials, source, active) values ('pa_syncope', 'palpitations', 'redflag', 7, 'yesno', null, 'Fainted, nearly fainted or had chest pain during palpitations?', 'क्या धड़कन के समय बेहोशी, चक्कर या सीने में दर्द हुआ?', 'धडधडीच्या वेळी बेशुद्धी, भोवळ किंवा छातीत दुखले का?', 'Palpitations with syncope/chest pain', null, null, null, true, 'Palpitations with syncope/chest pain — possible serious arrhythmia (ECG now)', null, null, array['Ventricular tachycardia','SVT / tachyarrhythmia']::text[], 'Hutchison 24e, Ch 13, p194-195', true) on conflict (id) do update set complaint_id=excluded.complaint_id, section=excluded.section, ord=excluded.ord, qtype=excluded.qtype, options=excluded.options, text_en=excluded.text_en, text_hi=excluded.text_hi, text_mr=excluded.text_mr, clinical_term=excluded.clinical_term, dedupe_key=excluded.dedupe_key, show_if=excluded.show_if, applies_to=excluded.applies_to, red_flag=excluded.red_flag, red_flag_note=excluded.red_flag_note, positive_means=excluded.positive_means, negative_means=excluded.negative_means, differentials=excluded.differentials, source=excluded.source, active=excluded.active, reviewed_on=current_date;
insert into public.hx_questions(id, complaint_id, section, ord, qtype, options, text_en, text_hi, text_mr, clinical_term, dedupe_key, show_if, applies_to, red_flag, red_flag_note, positive_means, negative_means, differentials, source, active) values ('pa_exertion', 'palpitations', 'redflag', 8, 'yesno', null, 'Palpitations brought on by exercise?', 'क्या धड़कन कसरत/मेहनत करते समय होती है?', 'धडधड व्यायाम/श्रम करताना होते का?', 'Exercise-induced palpitations', null, '{"q": "pa_triggers", "has": "exercise"}'::jsonb, null, true, 'Exertional palpitations — exclude structural heart disease / VT', null, null, array['Ventricular tachycardia','Hypertrophic cardiomyopathy']::text[], 'Hutchison 24e, Ch 13, p194', true) on conflict (id) do update set complaint_id=excluded.complaint_id, section=excluded.section, ord=excluded.ord, qtype=excluded.qtype, options=excluded.options, text_en=excluded.text_en, text_hi=excluded.text_hi, text_mr=excluded.text_mr, clinical_term=excluded.clinical_term, dedupe_key=excluded.dedupe_key, show_if=excluded.show_if, applies_to=excluded.applies_to, red_flag=excluded.red_flag, red_flag_note=excluded.red_flag_note, positive_means=excluded.positive_means, negative_means=excluded.negative_means, differentials=excluded.differentials, source=excluded.source, active=excluded.active, reviewed_on=current_date;
insert into public.hx_questions(id, complaint_id, section, ord, qtype, options, text_en, text_hi, text_mr, clinical_term, dedupe_key, show_if, applies_to, red_flag, red_flag_note, positive_means, negative_means, differentials, source, active) values ('pa_thyroid', 'palpitations', 'associated', 9, 'multi', '[{"v": "weightloss_heat", "en": "Weight loss, sweating, can''t tolerate heat", "hi": "वज़न घटना, पसीना, गर्मी सहन न होना", "mr": "वजन घटणे, घाम, उष्णता सहन न होणे", "ddx": ["Thyrotoxicosis"]}, {"v": "tremor", "en": "Hand tremor", "hi": "हाथ काँपना", "mr": "हात थरथरणे", "ddx": ["Thyrotoxicosis", "Anxiety / panic"]}, {"v": "pale_tired", "en": "Pale, tired", "hi": "पीला पड़ना, थकान", "mr": "फिकट, थकवा", "ddx": ["Anaemia"]}, {"v": "fear_tingling", "en": "Fear of dying, tingling fingers, fast breathing", "hi": "मरने का डर, उँगलियों में झुनझुनी, तेज़ साँस", "mr": "मरण्याची भीती, बोटांना मुंग्या, जलद श्वास", "ddx": ["Anxiety / panic"]}, {"v": "fever", "en": "Fever", "hi": "बुखार", "mr": "ताप", "ddx": ["Sinus tachycardia"]}]'::jsonb, 'Any of these too?', 'इनमें से कुछ और भी?', 'यापैकी काही आणखी?', 'Systemic features', null, null, null, false, null, null, null, '{}'::text[], 'General clinical practice', true) on conflict (id) do update set complaint_id=excluded.complaint_id, section=excluded.section, ord=excluded.ord, qtype=excluded.qtype, options=excluded.options, text_en=excluded.text_en, text_hi=excluded.text_hi, text_mr=excluded.text_mr, clinical_term=excluded.clinical_term, dedupe_key=excluded.dedupe_key, show_if=excluded.show_if, applies_to=excluded.applies_to, red_flag=excluded.red_flag, red_flag_note=excluded.red_flag_note, positive_means=excluded.positive_means, negative_means=excluded.negative_means, differentials=excluded.differentials, source=excluded.source, active=excluded.active, reviewed_on=current_date;
