insert into public.hx_questions(id, complaint_id, section, ord, qtype, options, text_en, text_hi, text_mr, clinical_term, dedupe_key, show_if, applies_to, red_flag, red_flag_note, positive_means, negative_means, differentials, source, active) values ('pa_fh_sudden', 'palpitations', 'redflag', 11, 'yesno', null, 'Anyone in family died suddenly young (under 40) or has heart muscle disease?', 'क्या परिवार में किसी की 40 से कम उम्र में अचानक मौत हुई या दिल की मांसपेशी की बीमारी है?', 'कुटुंबात कोणाचा 40 पेक्षा कमी वयात अचानक मृत्यू झाला आहे का किंवा हृदयस्नायूचा आजार आहे का?', 'Family history of sudden death', 'fh_sudden_death', null, null, true, 'Family history of sudden cardiac death — inherited heart disease?', null, null, array['Hypertrophic cardiomyopathy','Inherited arrhythmia']::text[], 'Hutchison 24e, Ch 13, p189', true) on conflict (id) do update set complaint_id=excluded.complaint_id, section=excluded.section, ord=excluded.ord, qtype=excluded.qtype, options=excluded.options, text_en=excluded.text_en, text_hi=excluded.text_hi, text_mr=excluded.text_mr, clinical_term=excluded.clinical_term, dedupe_key=excluded.dedupe_key, show_if=excluded.show_if, applies_to=excluded.applies_to, red_flag=excluded.red_flag, red_flag_note=excluded.red_flag_note, positive_means=excluded.positive_means, negative_means=excluded.negative_means, differentials=excluded.differentials, source=excluded.source, active=excluded.active, reviewed_on=current_date;
