date;
insert into public.hx_questions(id, complaint_id, section, ord, qtype, options, text_en, text_hi, text_mr, clinical_term, dedupe_key, show_if, applies_to, red_flag, red_flag_note, positive_means, negative_means, differentials, source, active) values ('sy_position', 'syncope', 'hopi', 2, 'choice', '[{"v": "standing_long", "en": "Standing for a long time / hot crowded place", "hi": "देर तक खड़े / गर्म भीड़ वाली जगह", "mr": "बराच वेळ उभे / गरम गर्दीची जागा", "ddx": ["Vasovagal syncope"]}, {"v": "getting_up", "en": "Getting up from lying/sitting", "hi": "लेटे/बैठे से उठते समय", "mr": "झोपलेल्या/बसलेल्या स्थितीतून उठताना", "ddx": ["Postural hypotension"]}, {"v": "exertion", "en": "During exercise / exertion", "hi": "मेहनत / कसरत के दौरान", "mr": "श्रम / व्यायाम करताना", "ddx": ["Cardiac syncope (arrhythmia / aortic stenosis)", "Hypertrophic cardiomyopathy"]}, {"v": "lying", "en": "Lying down", "hi": "लेटे हुए", "mr": "झोपलेले असताना", "ddx": ["Cardiac syncope (arrhythmia / aortic stenosis)", "Seizure"]}, {"v": "pain_fear_blood", "en": "Pain / fear / sight of blood / injection", "hi": "दर्द / डर / खून देखकर / इंजेक्शन", "mr": "वेदना / भीती / रक्त पाहून / इंजेक्शन", "ddx": ["Vasovagal syncope"]}, {"v": "cough_urine", "en": "Coughing / passing urine / straining", "hi": "खाँसते / पेशाब करते / ज़ोर लगाते", "mr": "खोकताना / लघवी करताना / जोर लावताना", "ddx": ["Situational syncope"]}, {"v": "neck_turn", "en": "Turning head / shaving / tight collar", "hi": "गर्दन घुमाना / दाढ़ी बनाना / टाइट कॉलर", "mr": "मान वळवणे / दाढी करणे / घट्ट कॉलर", "ddx": ["Carotid sinus hypersensitivity"]}]'::jsonb, 'What was the patient doing?', 'उस समय मरीज़ क्या कर रहा था?', 'त्या वेळी रुग्ण काय करत होता?', 'Circumstances', null, null, null, false, null, null, null, '{}'::text[], 'Hutchison 24e, Ch 13, p194-195', true) on conflict (id) do update set complaint_id=excluded.complaint_id, section=excluded.section, ord=excluded.ord, qtype=excluded.qtype, options=excluded.options, text_en=excluded.text_en, text_hi=excluded.text_hi, text_mr=excluded.text_mr, clinical_term=excluded.clinical_term, dedupe_key=excluded.dedupe_key, show_if=excluded.show_if, applies_to=excluded.applies_to, red_flag=excluded.red_flag, red_flag_note=excluded.red_flag_note, positive_means=excluded.positive_means, negative_means=excluded.negative_means, differentials=excluded.differentials, source=excluded.source, active=excluded.active, reviewed_on=current_date;
insert into public.hx_questions(id, complaint_id, section, ord, qtype, options, text_en, text_hi, text_mr, clinical_term, dedupe_key, show_if, applies_to, red_flag, red_flag_note, positive_means, negative_means, differentials, source, active) values ('sy_exertion', 'syncope', 'redflag', 3, 'yesno', null, 'Did the blackout happen during exertion?', 'क्या बेहोशी मेहनत/कसरत करते समय हुई?', 'बेशुद्धी श्रम/व्यायाम करताना झाली का?', 'Exertional syncope', null, null, null, true, 'Exertional syncope — aortic stenosis / cardiomyopathy / arrhythmia (urgent ECG/echo)', null, null, array['Cardiac syncope (arrhythmia / aortic stenosis)','Hypertrophic cardiomyopathy']::text[], 'Hutchison 24e, Ch 13, p194-195', true) on conflict (id) do update set complaint_id=excluded.complaint_id, section=excluded.section, ord=excluded.ord, qtype=excluded.qtype, options=excluded.options, text_en=excluded.text_en, text_hi=excluded.text_hi, text_mr=excluded.text_mr, clinical_term=excluded.clinical_term, dedupe_key=excluded.dedupe_key, show_if=excluded.show_if, applies_to=excluded.applies_to, red_flag=excluded.red_flag, red_flag_note=excluded.red_flag_note, positive_means=excluded.positive_means, negative_means=excluded.negative_means, differentials=excluded.differentials, source=excluded.source, active=excluded.active, reviewed_on=current_date;
