insert into public.hx_questions(id, complaint_id, section, ord, qtype, options, text_en, text_hi, text_mr, clinical_term, dedupe_key, show_if, applies_to, red_flag, red_flag_note, positive_means, negative_means, differentials, source, active) values ('sz_witness', 'seizure', 'hopi', 3, 'multi', '[{"v": "stiff_jerk", "en": "Stiffened then jerking of all limbs", "hi": "शरीर अकड़ा फिर सभी अंगों में झटके", "mr": "शरीर ताठ मग सर्व अवयवांना झटके", "ddx": ["Epilepsy"]}, {"v": "one_side_jerk", "en": "Jerking of one side / one limb", "hi": "एक तरफ / एक अंग में झटके", "mr": "एका बाजूला / एका अवयवाला झटके", "ddx": ["Focal seizure (structural cause)"]}, {"v": "eyes_open", "en": "Eyes open, rolled up", "hi": "आँखें खुली, ऊपर चढ़ी", "mr": "डोळे उघडे, वर फिरलेले", "ddx": ["Epilepsy"]}, {"v": "eyes_shut_resist", "en": "Eyes tightly shut, resisted opening, side-to-side movements", "hi": "आँखें कसकर बंद, खोलने नहीं दी, इधर-उधर हिलना", "mr": "डोळे घट्ट मिटलेले, उघडू दिले नाहीत, इकडे-तिकडे हालचाल", "ddx": ["Psychogenic non-epileptic attack"]}, {"v": "tongue", "en": "Bitten side of tongue", "hi": "जीभ का किनारा कटा", "mr": "जिभेची कडा चावली", "ddx": ["Epilepsy"]}, {"v": "urine", "en": "Passed urine", "hi": "पेशाब निकल गया", "mr": "लघवी झाली", "ddx": ["Epilepsy"]}, {"v": "blue", "en": "Turned blue", "hi": "नीला पड़ गया", "mr": "निळा पडला", "ddx": ["Epilepsy"]}, {"v": "staring", "en": "Only staring / lip smacking / fiddling", "hi": "सिर्फ़ घूरना / होंठ चबाना / हाथ से कुछ करना", "mr": "फक्त टक लावणे / ओठ चघळणे / हाताने चाळा", "ddx": ["Focal seizure (structural cause)"]}]'::jsonb, 'What did the witness see? (ask the person who saw it)', 'देखने वाले ने क्या देखा? (जिसने देखा उससे पूछें)', 'पाहणाऱ्याने काय पाहिले? (ज्यांनी पाहिले त्यांना विचारा)', 'Witness account', null, null, null, false, null, null, null, '{}'::text[], 'Hutchison 24e, Ch 16, p310 (Table 16.1)', true) on conflict (id) do update set complaint_id=excluded.complaint_id, section=excluded.section, ord=excluded.ord, qtype=excluded.qtype, options=excluded.options, text_en=excluded.text_en, text_hi=excluded.text_hi, text_mr=excluded.text_mr, clinical_term=excluded.clinical_term, dedupe_key=excluded.dedupe_key, show_if=excluded.show_if, applies_to=excluded.applies_to, red_flag=excluded.red_flag, red_flag_note=excluded.red_flag_note, positive_means=excluded.positive_means, negative_means=excluded.negative_means, differentials=excluded.differentials, source=excluded.source, active=excluded.active, reviewed_on=current_date;
